-- 014_spec_pages.sql — GENERATED by db/content/build_specs_sql.py; edit db/content/specs/*.py.
SET client_min_messages = warning;
CREATE TABLE IF NOT EXISTS spec_pages (
  id           SERIAL PRIMARY KEY,
  make_slug    TEXT NOT NULL,
  model_slug   TEXT NOT NULL,
  topic        TEXT NOT NULL,
  make_name    TEXT NOT NULL,
  model_name   TEXT NOT NULL,
  topic_label  TEXT NOT NULL,
  title        TEXT NOT NULL,
  seo_title    TEXT NOT NULL,
  meta_desc    TEXT NOT NULL,
  faq          JSONB NOT NULL DEFAULT '[]',
  page         JSONB NOT NULL,
  status       TEXT NOT NULL DEFAULT 'draft',
  published_at DATE,                                  -- set the first time the page is published, never changed
  updated_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (make_slug, model_slug, topic)
);

INSERT INTO spec_pages (make_slug, model_slug, topic, make_name, model_name, topic_label, title, seo_title, meta_desc, faq, page, status, published_at)
VALUES ('ford', 'maverick', 'bed-dimensions', $s$Ford$s$, $s$Maverick$s$, $s$Bed size$s$, $s$Ford Maverick Bed Size: Length, Width and Height in Inches$s$, $s$Ford Maverick Bed Size: Length, Width and Height$s$, $s$Ford Maverick bed size from Ford's spec sheets: 54.4 in long, 42.6 in between the wheelhouses, 20.3 in deep, 33.3 cu ft, plus lift-in height and payload.$s$, $s$[{"q": "How long is the Ford Maverick bed?", "a": "54.4 in (about 4.5 ft) at the floor with the tailgate closed, according to Ford's 2025 and 2026 specification sheets. Ford's website gives 72 in (6 ft) of floor length with the tailgate open."}, {"q": "How wide is the Maverick bed between the wheel wells?", "a": "42.6 in. The bed is 53.3 in wide wall to wall, so a 48 in sheet lies flat above the wheelhouses but not between them."}, {"q": "Is the bed the same on the Tremor and Lobo?", "a": "Yes for the box itself: Ford's sheets list one set of bed dimensions for every Maverick. What changes is the lift-in height and the payload."}, {"q": "Does every Maverick have the same bed length?", "a": "In the model years on this page, yes. The Maverick is sold in one cab and one bed length."}]$s$::jsonb, $s${"answer": "The Ford Maverick bed is 54.4 in (about 4.5 ft) long at the floor, 42.6 in wide between the wheelhouses, 53.3 in wide wall to wall and 20.3 in deep, with 33.3 cu ft of volume. With the tailgate open the floor is 72 in (6 ft) long. The Maverick comes with one bed size.", "reviewed": "2026-11-16", "covers": "Model years 2025, 2026 and 2027", "not_covered": "2022 to 2024: Ford's sheets for these years are not on this page yet.", "sections": [{"id": "bed", "h": "Maverick bed dimensions", "table": {"head": ["Measurement", "Figure"], "rows": [["Bed length at the floor, tailgate closed", "54.4 in", [1, 2, 3]], ["Floor length with the tailgate open", "72 in", 3], ["Bed length at the top of the body", "53.1 in", [1, 2]], ["Width between the wheelhouses", "42.6 in", [1, 2, 3]], ["Width, wall to wall", "53.3 in", [1, 2, 3]], ["Rear opening width, top of the box", "49.8 in", [1, 2]], ["Rear opening width, lower", "48.8 in", [1, 2]], ["Bed height", "20.3 in", [1, 2]], ["Cargo volume", "33.3 cu ft", [1, 2, 3]]]}}, {"id": "lift-in", "h": "Lift-in height by powertrain (2026)", "intro": "The lift-in height is how far the open tailgate sits above the ground.", "table": {"head": ["Powertrain or trim", "Lift-in height"], "rows": [["2.5L Hybrid, FWD", "30.4 in", [1, 2]], ["2.5L Hybrid, AWD", "29.4 in", 1], ["2.0L EcoBoost, FWD", "30.5 in", 1], ["2.0L EcoBoost, AWD", "29.4 in", [1, 2]], ["Tremor", "30.0 in", [1, 2]], ["Lobo", "28.2 in", [1, 2]]]}}, {"id": "payload", "h": "Maximum payload by powertrain (2026)", "table": {"head": ["Powertrain or trim", "Maximum payload"], "rows": [["2.5L Hybrid, FWD", "1,500 lb", [1, 2]], ["2.5L Hybrid, AWD", "1,400 lb", [1, 2]], ["2.0L EcoBoost, FWD", "1,500 lb", 1], ["2.0L EcoBoost, AWD", "1,500 lb", [1, 2]], ["Tremor", "1,140 lb", [1, 2]], ["Lobo", "1,045 lb", [1, 2]]]}, "notes": ["Payload includes passengers. The figure for your truck is on the yellow tire and loading label on the driver's door jamb."]}], "check": ["Measure the floor from the bulkhead to the inside of the closed tailgate. It should read about 54 in.", "Buying a tonneau cover or a bed rack: order by model year and the 4.5 ft bed. Covers for other trucks do not fit.", "Carrying long loads: with the tailgate open the floor is 72 in long; anything longer overhangs the tailgate.", "Your owner's manual and the labels on your truck override this page."], "related": ["tonneau-covers", "bed-racks"], "sources": [["Ford, 2026 Maverick Technical Specifications", "https://www.fromtheroad.ford.com/content/dam/fordmediasite/us/en/library/2026/specs/2026_Ford_Maverick_Specs.pdf"], ["Ford, 2025 Maverick and Lobo Technical Specifications", "https://www.fromtheroad.ford.com/content/dam/fordmediasite/us/en/library/2025/specs/2025-Ford-Maverick-and-Lobo-Technical-Specs.pdf"], ["Ford.com, Maverick specifications (2027 model year page, read 16 Nov 2026)", "https://www.ford.com/trucks/maverick/specs/"]]}$s$::jsonb, 'draft', NULL)
ON CONFLICT (make_slug, model_slug, topic) DO UPDATE SET make_name=EXCLUDED.make_name, model_name=EXCLUDED.model_name, topic_label=EXCLUDED.topic_label,
  title=EXCLUDED.title, seo_title=EXCLUDED.seo_title, meta_desc=EXCLUDED.meta_desc, faq=EXCLUDED.faq, page=EXCLUDED.page, status=EXCLUDED.status,
  published_at=COALESCE(spec_pages.published_at, EXCLUDED.published_at), updated_at=now();

INSERT INTO spec_pages (make_slug, model_slug, topic, make_name, model_name, topic_label, title, seo_title, meta_desc, faq, page, status, published_at)
VALUES ('toyota', 'tacoma', 'towing-capacity', $s$Toyota$s$, $s$Tacoma$s$, $s$Towing capacity$s$, $s$Toyota Tacoma Towing Capacity by Year, Cab and Grade$s$, $s$Toyota Tacoma Towing Capacity by Year, Cab and Grade$s$, $s$Toyota Tacoma towing capacity from Toyota's spec tables: 3,500 to 6,500 lb for 2024, up to 6,800 lb for 2021 and 2023, by cab, grade and engine.$s$, $s$[{"q": "How much can a Toyota Tacoma tow?", "a": "It depends on the year and the build. Toyota's 2024 specification table lists 3,500 lb for the SR and up to 6,500 lb for the XtraCab SR5 and TRD PreRunner. For 2021 and 2023, Toyota lists 3,500 lb with the 2.7L four-cylinder and 6,400 to 6,800 lb with the 3.5L V6, depending on cab and drivetrain."}, {"q": "Which Tacoma tows the most?", "a": "In the brochures we read, the highest figure is 6,800 lb: a 2021 or 2023 Access Cab with the 3.5L V6, automatic transmission and 4x2. For the 2024 truck the highest figure is 6,500 lb, on the XtraCab SR5 and TRD PreRunner."}, {"q": "Does the hybrid Tacoma tow more?", "a": "Not in Toyota's 2024 table. The TRD Pro and Trailhunter, which come only with the i-FORCE MAX hybrid, are listed at 6,000 lb, below the 6,400 lb of the non-hybrid Double Cab SR5."}, {"q": "Is the towing capacity on this page the limit for my truck?", "a": "No. It is the figure Toyota published for that configuration. The limit for your truck is on its door-jamb labels and in its owner's manual, and it drops with passengers and cargo on board."}]$s$::jsonb, $s${"answer": "A Toyota Tacoma tows between 3,500 and 6,800 lb, depending on model year, engine, cab and drivetrain. The 2024 Tacoma is rated at 3,500 lb (SR) to 6,500 lb (XtraCab SR5 and TRD PreRunner). The 2021 and 2023 trucks are rated at 3,500 lb with the 2.7L four-cylinder and 6,400 to 6,800 lb with the 3.5L V6.", "reviewed": "2026-11-16", "covers": "Model years 2021, 2023, 2024 and 2025", "not_covered": "2016 to 2020, 2022 and 2026: Toyota's tables for these years are not on this page yet.", "sections": [{"id": "2024", "h": "2024 Tacoma (4th generation)", "intro": "Toyota's 2024 brochure lists one maximum towing weight per cab and grade.", "table": {"head": ["Cab", "Grade", "Maximum towing (lb)"], "rows": [["XtraCab", "SR", "3,500", 1], ["XtraCab", "SR5", "6,500", [1, 3]], ["XtraCab", "TRD PreRunner", "6,500", [1, 3]], ["Double Cab", "SR", "3,500", 1], ["Double Cab", "SR5", "6,400", 1], ["Double Cab", "TRD Sport", "6,400", 1], ["Double Cab", "TRD Off-Road", "6,400", 1], ["Double Cab", "Limited", "6,300", 1], ["Double Cab", "Trailhunter", "6,000", 1], ["Double Cab", "TRD Pro", "6,000", 1]]}, "notes": ["Trailhunter and TRD Pro come only with the i-FORCE MAX hybrid powertrain."]}, {"id": "2025", "h": "2025 Tacoma", "table": {"head": ["What Toyota states", "Figure"], "rows": [["Maximum towing capacity, whole lineup", "Up to 6,500 lb", 2]]}, "notes": ["Toyota's 2025 release gives the lineup maximum only. It does not break the figure down by cab or grade."]}, {"id": "2021-2023", "h": "2021 and 2023 Tacoma (3rd generation)", "intro": "Toyota's 2021 and 2023 brochures print the same figures. The table shows 4x2 and 4x4; a dash means Toyota lists no figure for that combination.", "table": {"head": ["Engine and transmission", "Cab", "Grade", "4x2 (lb)", "4x4 (lb)"], "rows": [["2.7L four-cylinder, automatic", "Access Cab", "SR, SR5", "3,500", "3,500", [4, 5]], ["2.7L four-cylinder, automatic", "Double Cab", "SR, SR5", "3,500", "—", [4, 5]], ["3.5L V6, automatic", "Access Cab", "SR, SR5, TRD Sport", "6,800", "6,500", [4, 5]], ["3.5L V6, automatic", "Access Cab", "TRD Off-Road", "—", "6,500", [4, 5]], ["3.5L V6, automatic", "Double Cab", "SR", "—", "6,400", [4, 5]], ["3.5L V6, automatic", "Double Cab", "SR5, TRD Sport, TRD Off-Road", "6,700", "6,400", [4, 5]], ["3.5L V6, automatic", "Double Cab", "Limited", "6,600", "6,400", [4, 5]], ["3.5L V6, automatic", "Double Cab", "TRD Pro", "—", "6,400", [4, 5]], ["3.5L V6, manual", "Access Cab", "TRD Sport, TRD Off-Road", "—", "6,500", [4, 5]], ["3.5L V6, manual", "Double Cab", "TRD Sport, TRD Off-Road, TRD Pro", "—", "6,400", [4, 5]]]}, "notes": ["Double Cab long-bed trucks have their own row in Toyota's table. We could not match its values to grades with certainty, so they are left out."]}], "check": ["Find your cab, grade, engine and drivetrain in the table. The figure applies to that combination only.", "Read the labels on the driver's door jamb. The trailer you can pull also depends on your truck's gross combined weight rating, minus the truck, passengers and cargo.", "Check the tongue weight limit in your owner's manual before choosing a hitch or a ball mount.", "Your owner's manual and the labels on your truck override this page."], "related": ["hitches", "bed-racks", "tonneau-covers"], "sources": [["Toyota, 2024 Tacoma eBrochure, specifications table", "https://www.toyota.com/content/dam/toyota/brochures/pdf/2024/tacoma_ebrochure.pdf"], ["Toyota Newsroom, The 2025 Toyota Tacoma is Ready for Adventure (17 Dec 2024)", "https://pressroom.toyota.com/?generate_pdf=97924"], ["Toyota Newsroom, All-New 2024 Toyota Tacoma is Adventure Ready Out of the Box", "https://pressroom.toyota.com/all-new-2024-toyota-tacoma-is-adventure-ready-out-of-the-box/"], ["Toyota, 2023 Tacoma eBrochure, specifications table", "https://www.toyota.com/content/dam/toyota/brochures/pdf/2023/tacoma_ebrochure.pdf"], ["Toyota, 2021 Tacoma eBrochure, specifications table", "https://www.toyota.com/content/dam/toyota/brochures/pdf/2021/tacoma_ebrochure.pdf"]]}$s$::jsonb, 'draft', NULL)
